<?php
declare(strict_types=1);
namespace Namira;
use PDO;
/** Presentation policies over Archive/MartyrFilters/GalleryFacets; no separate search index. */
final class PublicSearch {
 public const BASIC=['topic'=>'دسته‌بندی موضوعی','geo_country'=>'کشور محل تولد','geo_province'=>'استان محل تولد','geo_county'=>'شهرستان محل تولد','geo_city'=>'شهر محل تولد'];
 public const LEGACY=['job'=>'شغل متنی پرونده','organization'=>'سازمان متنی پرونده','province'=>'استان قدیمی؛ نوع مکان نامشخص','city'=>'شهر قدیمی؛ نوع مکان نامشخص'];
 public const TEXT=['summary'=>'خلاصه زندگی‌نامه','biography'=>'زندگی‌نامه','will_text'=>'وصیت‌نامه','memories'=>'خاطرات'];
 public const MEDIA=['kind'=>'نوع تصویر','media_type'=>'نوع رسانه','artist_id'=>'هنرمند','mime'=>'فرمت فایل','orientation'=>'جهت تصویر','download'=>'امکان دریافت اصل'];
 public static function people(array $in):bool {$v=Security::text($in,'results',12,false)?:'images';if(!in_array($v,['images','martyrs'],true))throw new HttpError(422,'نوع نتایج معتبر نیست.');return $v==='martyrs';}
 private static function clean(mixed $value):mixed {if(!is_array($value))return $value;$out=[];foreach($value as $k=>$v){$v=self::clean($v);if($v!==''&&$v!==null&&$v!==[])$out[$k]=$v;}return $out;}
 public static function input(PDO $db,array $in,bool $advanced=false):array {
  $f=self::clean(MartyrFilters::galleryInput($in));if(!is_array($f))$f=[];$sort=Security::text($f,'sort',20,false);if($sort!==''&&!in_array($sort,['new','name','downloads'],true))throw new HttpError(422,'مرتب‌سازی معتبر نیست.');
  if($advanced){$legacy=[];foreach(GalleryFacets::LEVELS as $level)if(($f['geo_'.$level]??'')!=='')$legacy[$level]=$f['geo_'.$level];$role=Security::text($f,'geo_role',40,false);if($legacy||$role!==''){$role=$role?:'residence_at_incident';if(!isset(GalleryFacets::ROLES[$role]))throw new HttpError(422,'نوع مکان معتبر نیست.');if(!$legacy)$legacy['present']='1';$f['places'][$role]=array_replace($legacy,(array)($f['places'][$role]??[]));}foreach(['geo_role','geo_country','geo_province','geo_county','geo_city'] as $key)unset($f[$key]);
   if(($f['year_from']??'')!==''||($f['year_to']??'')!==''){$key=Security::text($f,'date_kind',30,false)?:'martyrdom_date';$f['dates'][$key]=array_replace(['calendar'=>$f['calendar']??'jalali','from'=>$f['year_from']??'','to'=>$f['year_to']??''],(array)($f['dates'][$key]??[]));}foreach(['date_kind','calendar','year_from','year_to'] as $key)unset($f[$key]);
  }else{$f=array_intersect_key($f,array_flip(['q','axis','p','sort','geo_country','geo_province','geo_county','geo_city']));if(isset($f['axis'])){if(!is_array($f['axis']))throw new HttpError(422,'موضوع معتبر نیست.');$f['axis']=array_intersect_key($f['axis'],['collection'=>1]);}foreach(GalleryFacets::LEVELS as $level)if(($f['geo_'.$level]??'')!==''){$f['geo_role']='birth_place';break;}}
  $f=GalleryFacets::input($db,$f);(new Archive($db))->conditions($f);Archive::mediaConditions($f);return self::clean($f);
 }
 public static function advancedRequired(array $in):bool {
  $f=self::clean(MartyrFilters::galleryInput($in));foreach($f as $key=>$v){if(in_array($key,['q','p','sort','geo_country','geo_province','geo_county','geo_city'],true))continue;if($key==='axis'&&is_array($v)&&!array_diff(array_keys($v),['collection']))continue;if($key==='geo_role'&&$v==='birth_place'&&array_filter(array_intersect_key($f,array_flip(['geo_country','geo_province','geo_county','geo_city']))))continue;return true;}return false;
 }
 public static function advancedLink(array $f,bool $people=false):string {return url('advanced-search',['results'=>$people?'martyrs':'images']+$f);}
 public static function hidden(array $values,array $exclude=[],string $prefix=''):void {foreach($values as $key=>$value){if($prefix===''&&in_array($key,$exclude,true))continue;$name=$prefix===''?(string)$key:$prefix.'['.(is_int($key)?'':$key).']';if(is_array($value))self::hidden($value,[],$name);else echo '<input type="hidden" name="'.e($name).'" value="'.e($value).'">';}}
 public static function basicOptions(PDO $db,array $f,bool $people=false):array {
  $o=GalleryFacets::options($db,$f,$people,['collection']);$o['geo']=GalleryFacets::geo($db,$f,'birth_place',$people);$o['geoDefaultRole']='birth_place';$o['roles']=[['id'=>'birth_place','title'=>'محل تولد']];$o['hasDates']=false;$o['chips']=[];foreach(self::BASIC as $key=>$title)$o['chips'][]=compact('key','title');return $o;
 }
 public static function clearDescendants(array &$f,string $changed,bool $advanced=false):array {
  if($changed==='')return [];$role=null;if($advanced){$p=explode('.',$changed);if(count($p)!==2||!isset(GalleryFacets::ROLES[$p[0]])||!in_array($p[1],GalleryFacets::LEVELS,true))throw new HttpError(422,'سطح جغرافیایی معتبر نیست.');[$role,$level]=$p;}
  else {$level=str_starts_with($changed,'geo_')?substr($changed,4):'';if(!in_array($level,GalleryFacets::LEVELS,true))throw new HttpError(422,'سطح جغرافیایی معتبر نیست.');}
  $cleared=[];$start=array_search($level,GalleryFacets::LEVELS,true);foreach(array_slice(GalleryFacets::LEVELS,$start+1) as $child){if($advanced){if(isset($f['places'][$role][$child])){$cleared[]=$role.'.'.$child;unset($f['places'][$role][$child]);}}elseif(isset($f['geo_'.$child])){$cleared[]='geo_'.$child;unset($f['geo_'.$child]);}}return $cleared;
 }
 public static function basicResponse(PDO $db,array $in,bool $people=false):array {
  $f=self::input($db,$in);$cleared=self::clearDescendants($f,Security::text($in,'changed',40,false));if(!array_filter(array_intersect_key($f,array_flip(['geo_country','geo_province','geo_county','geo_city']))))unset($f['geo_role']);$o=self::basicOptions($db,$f,$people);$data=['filters'=>$f,'facets'=>$o,'count'=>GalleryFacets::count($db,$f,$people),'cleared'=>$cleared,'url'=>url($people?'martyrs':'gallery',$f),'advancedUrl'=>self::advancedLink($f,$people)];
  if(($in['mode']??'')==='results'){$result=self::listing($db,$f,$people);$data['count']=$result['count'];ob_start();view($people?'martyr-results':'gallery-results',compact('result','f'));$data['html']=ob_get_clean();ob_start();view('martyr-filter-tags',['db'=>$db,'f'=>$f,'filterRoute'=>$people?'martyrs':'gallery']);$data['tags']=ob_get_clean();}return $data;
 }
 public static function listing(PDO $db,array $f,bool $people):array {return $people?MartyrDirectory::listing($db,$f,max(1,(int)($f['p']??1))):(new Archive($db))->images($f,max(1,(int)($f['p']??1)));}
 private static function mediaBase(PDO $db,array $f,bool $people):array {[$from,$where,$args]=GalleryFacets::base($db,$f,$people);if($people){$from.=' JOIN media_public_martyrs rel ON rel.martyr_id=m.id JOIN images i ON i.id=rel.image_id JOIN media_publication ip ON ip.image_id=i.id';[$sql,$params]=Archive::mediaConditions($f,false,'i','ip');$where.=' AND '.$sql;$args=[...$args,...$params];}return [$from,$where,$args];}
 public static function options(PDO $db,array $f,bool $people=false):array {
  $facets=GalleryFacets::options($db,$f,$people);$places=[];
  foreach(GalleryFacets::ROLES as $role=>$title){$context=$f;unset($context['places'][$role]);$geoFilter=$context;foreach((array)($f['places'][$role]??[]) as $k=>$v)if(in_array($k,GalleryFacets::LEVELS,true))$geoFilter['geo_'.$k]=$v;$geo=GalleryFacets::geo($db,$geoFilter,$role,$people);if(array_filter($geo)||!empty($f['places'][$role]))$places[$role]=['title'=>$title,'levels'=>$geo];}
  $dates=[];foreach(['birth_date'=>'تاریخ تولد','martyrdom_date'=>'تاریخ شهادت'] as $key=>$title){$context=$f;unset($context['dates'][$key]);[$from,$where,$args]=GalleryFacets::base($db,$context,$people);$rows=Db::query($db,'SELECT df.calendar,MIN(df.year) AS first_year,MAX(df.year) AS last_year '.$from.' JOIN martyr_public_facts df ON df.martyr_id=m.id WHERE '.$where.' AND df.fact_key=? AND df.year BETWEEN 1 AND 9999 AND df.calendar IN (?,?,?) GROUP BY df.calendar',[...$args,$key,'jalali','gregorian','hijri'])->fetchAll();if($rows||!empty($f['dates'][$key]))$dates[$key]=['title'=>$title,'calendars'=>$rows];}
  $legacy=[];foreach(self::LEGACY as $key=>$title){$context=$f;unset($context[$key]);[$from,$where,$args]=GalleryFacets::base($db,$context,$people);$rows=Db::query($db,'SELECT DISTINCT TRIM(m.'.$key.') AS id,TRIM(m.'.$key.') AS title '.$from.' WHERE '.$where." AND TRIM(m.$key)<>'' ORDER BY title",$args)->fetchAll();if($rows||($f[$key]??'')!=='')$legacy[$key]=compact('title','rows');}
  $context=$f;unset($context['category']);[$from,$where,$args]=GalleryFacets::base($db,$context,$people);$categories=Db::query($db,'SELECT DISTINCT c.id,c.name AS title '.$from.' JOIN martyr_categories mc ON mc.martyr_id=m.id JOIN categories c ON c.id=mc.category_id WHERE '.$where." AND TRIM(c.name)<>'' ORDER BY c.name",$args)->fetchAll();if($categories||!empty($f['category']))$legacy['category']=['title'=>'دسته‌بندی قدیمی پرونده','rows'=>$categories];
  $fields=[];$context=$f;unset($context['first_name'],$context['last_name'],$context['archive_code'],$context['text_field'],$context['text_query']);[$from,$where,$args]=GalleryFacets::base($db,$context,$people);foreach(['first_name'=>'نام','last_name'=>'نام خانوادگی','archive_code'=>'کد آرشیو']+self::TEXT as $key=>$title){$col=$key==='archive_code'?'code':$key;if(Db::query($db,'SELECT 1 '.$from.' WHERE '.$where." AND TRIM(m.$col)<>'' LIMIT 1",$args)->fetchColumn())$fields[$key]=$title;}
  $media=[];foreach(self::MEDIA as $key=>$title){$context=$f;unset($context[$key]);if($key==='kind')$context['kind']='all';[$from,$where,$args]=self::mediaBase($db,$context,$people);$join='';$column=match($key){'kind'=>'i.kind','media_type'=>'ip.type_id','artist_id'=>'sa.artist_id','mime'=>'i.mime','download'=>'ip.download_allowed','orientation'=>"CASE WHEN i.height>i.width THEN 'portrait' WHEN i.height<i.width THEN 'landscape' ELSE 'square' END"};$label=$column;
   if($key==='media_type'){$join=" JOIN protocol_terms st ON st.id=ip.type_id AND st.taxonomy='media_type' AND st.active=1";$label='st.title';}elseif($key==='artist_id'){$join=' JOIN media_public_artists sa ON sa.image_id=i.id JOIN artists ar ON ar.id=sa.artist_id AND ar.public_visible=1 AND ar.archived=0';$label='ar.public_snapshot';}
   $rows=Db::query($db,'SELECT DISTINCT '.$column.' AS id,'.$label.' AS title '.$from.$join.' WHERE '.$where.' ORDER BY title',$args)->fetchAll();if($key==='artist_id'){foreach($rows as &$row){$snapshot=json_decode($row['title']??'{}',true);$row['title']=$snapshot['display_name']??$snapshot['name']??'';}unset($row);}$unique=[];foreach($rows as $row)$unique[(string)$row['id']]=$row;$rows=array_values($unique);$rows=array_values(array_filter($rows,fn($r)=>$r['id']!==null&&trim((string)$r['id'])!==''&&trim((string)$r['title'])!==''));if($rows||($f[$key]??'')!=='')$media[$key]=compact('title','rows');
  }$mediaAvailable=(bool)$media;
  return ['axes'=>array_values(array_filter($facets['axes'],fn($a)=>$a['options']||!empty($f['axis'][$a['axis_key']]))),'places'=>$places,'dates'=>$dates,'legacy'=>$legacy,'fields'=>$fields,'media'=>$media,'mediaAvailable'=>$mediaAvailable,'people'=>$people];
 }
 public static function advancedResponse(PDO $db,array $in,bool $results=false):array {$people=self::people($in);$f=self::input($db,$in,true);$cleared=self::clearDescendants($f,Security::text($in,'changed',60,false),true);$options=self::options($db,$f,$people);$data=['filters'=>$f,'results'=>$people?'martyrs':'images','options'=>$options,'count'=>GalleryFacets::count($db,$f,$people),'cleared'=>$cleared,'url'=>url('advanced-search',['results'=>$people?'martyrs':'images']+$f)];if($results)$data['result']=self::listing($db,$f,$people);return $data;}
}
